document.getElementById("year").textContent=new Date().getFullYear();function goToLogin(){window.location.href="/login.html"}document.getElementById("heroLogin").addEventListener("click",goToLogin),document.getElementById("ctaLogin").addEventListener("click",goToLogin),document.getElementById("authBtn").addEventListener("click",goToLogin),document.getElementById("learnMore").addEventListener("click",function(){document.getElementById("features-heading").scrollIntoView({behavior:"smooth",block:"start"})}),document.getElementById("exploreBtn").addEventListener("click",function(){document.getElementById("testimonials-heading").scrollIntoView({behavior:"smooth",block:"center"})}),["authBtn","heroLogin","ctaLogin"].forEach(e=>{document.getElementById(e).addEventListener("keyup",function(o){(o.key==="Enter"||o.key===" ")&&(o.preventDefault(),goToLogin())})});const trustItems=document.querySelectorAll(".trust-item"),observer=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&t.target.classList.add("show")})},{threshold:.2});trustItems.forEach(e=>observer.observe(e)),document.querySelectorAll(".service-card").forEach(e=>{observer.observe(e)});const circles=document.querySelectorAll(".circle"),lines=document.querySelectorAll(".line"),workObserver=new IntersectionObserver(e=>{e.forEach(t=>{t.isIntersecting&&t.target.classList.add("show")})},{threshold:.5});circles.forEach(e=>workObserver.observe(e)),lines.forEach(e=>workObserver.observe(e)),document.querySelectorAll(".professional-card").forEach(e=>{observer.observe(e)}),document.querySelectorAll(".project-card").forEach(e=>{observer.observe(e)}),document.querySelectorAll(".feature-box").forEach(e=>{observer.observe(e)}),document.querySelectorAll(".dashboard-left,.dashboard-right").forEach(e=>observer.observe(e)),observer.observe(document.querySelector(".final-cta"));const topBtn=document.getElementById("backToTop");topBtn?.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})});
